urllib3.util.connection._set_socket_opti:
def _set_socket_options(sock: socket.socket, options: _TYPE_SOCKET_OPTIONS | None) -> None:
    if options is None:
        return
    for opt in options:
        sock.setsockopt(*opt)

urllib3.filepost.iter_field_objects:
def iter_field_objects(fields: _TYPE_FIELDS) -> typing.Iterable[RequestField]:
    """
    Iterate over fields.

    Supports list of (k, v) tuples and dicts, and lists of
    :class:`~urllib3.fields.RequestField`.

    """
    iterable: typing.Iterable[RequestField | tuple[(str, _TYPE_FIELD_VALUE_TUPLE)]]
    if isinstance(fields, typing.Mapping):
        iterable = fields.items()
    else:
        iterable = fields
    for field in iterable:
        if isinstance(field, RequestField):
            yield field
        else:
            yield RequestField.from_tuples(*field)

urllib3.util.ssl_._is_bpo_43522_fixed:
def _is_bpo_43522_fixed(implementation_name: str, version_info: _TYPE_VERSION_INFO, pypy_version_info: _TYPE_VERSION_INFO | None) -> bool:
    """Return True for CPython 3.9.3+ or 3.10+ and PyPy 7.3.8+ where
    setting SSLContext.hostname_checks_common_name to False works.

    Outside of CPython and PyPy we don't know which implementations work
    or not so we conservatively use our hostname matching as we know that works
    on all implementations.

    https://github.com/urllib3/urllib3/issues/2192#issuecomment-821832963
    https://foss.heptapod.net/pypy/pypy/-/issues/3539
    """
    if implementation_name == 'pypy':
        return pypy_version_info >= (7, 3, 8)
    elif implementation_name == 'cpython':
        major_minor = version_info[:2]
        micro = version_info[2]
        return ((major_minor == (3, 9) and micro >= 3) or major_minor >= (3, 10))
    else:
        return False

urllib3.util.ssl_._is_has_never_check_co:
def _is_has_never_check_common_name_reliable(openssl_version: str, openssl_version_number: int, implementation_name: str, version_info: _TYPE_VERSION_INFO, pypy_version_info: _TYPE_VERSION_INFO | None) -> bool:
    is_openssl = openssl_version.startswith('OpenSSL ')
    is_openssl_issue_14579_fixed = openssl_version_number >= 269488335
    return (is_openssl and ((is_openssl_issue_14579_fixed or _is_bpo_43522_fixed(implementation_name, version_info, pypy_version_info))))

urllib3.util.util.to_bytes:
def to_bytes(x: str | bytes, encoding: str | None = None, errors: str | None = None) -> bytes:
    if isinstance(x, bytes):
        return x
    elif not isinstance(x, str):
        raise TypeError(f'not expecting type {type(x).__name__}')
    if (encoding or errors):
        return x.encode((encoding or 'utf-8'), errors=(errors or 'strict'))
    return x.encode()

urllib3.util.request.body_to_chunks:
def body_to_chunks(body: typing.Any | None, method: str, blocksize: int) -> ChunksAndContentLength:
    """Takes the HTTP request method, body, and blocksize and
    transforms them into an iterable of chunks to pass to
    socket.sendall() and an optional 'Content-Length' header.

    A 'Content-Length' of 'None' indicates the length of the body
    can't be determined so should use 'Transfer-Encoding: chunked'
    for framing instead.
    """
    chunks: typing.Iterable[bytes] | None
    content_length: int | None
    if body is None:
        chunks = None
        if method.upper() not in _METHODS_NOT_EXPECTING_BODY:
            content_length = 0
        else:
            content_length = None
    elif isinstance(body, (str, bytes)):
        chunks = (to_bytes(body), )
        content_length = len(chunks[0])
    elif hasattr(body, 'read'):

        def chunk_readable() -> typing.Iterable[bytes]:
            encode = isinstance(body, io.TextIOBase)
            while True:
                datablock = body.read(blocksize)
                if not datablock:
                    break
                if encode:
                    datablock = datablock.encode('utf-8')
                yield datablock
        chunks = chunk_readable()
        content_length = None
    else:
        try:
            mv = memoryview(body)
        except TypeError:
            try:
                chunks = iter(body)
                content_length = None
            except TypeError:
                raise TypeError(f"'body' must be a bytes-like object, file-like object, or iterable. Instead was {body!r}") from None
        else:
            chunks = (body, )
            content_length = mv.nbytes
    return ChunksAndContentLength(chunks=chunks, content_length=content_length)

urllib3.util.request.set_file_position:
def set_file_position(body: typing.Any, pos: _TYPE_BODY_POSITION | None) -> _TYPE_BODY_POSITION | None:
    """
    If a position is provided, move file to that point.
    Otherwise, we'll attempt to record a position for future use.
    """
    if pos is not None:
        rewind_body(body, pos)
    elif getattr(body, 'tell', None) is not None:
        try:
            pos = body.tell()
        except OSError:
            pos = _FAILEDTELL
    return pos

urllib3.util.request.rewind_body:
def rewind_body(body: typing.IO[typing.AnyStr], body_pos: _TYPE_BODY_POSITION) -> None:
    """
    Attempt to rewind body to a certain position.
    Primarily used for request redirects and retries.

    :param body:
        File-like object that supports seek.

    :param int pos:
        Position to seek to in file.
    """
    body_seek = getattr(body, 'seek', None)
    if (body_seek is not None and isinstance(body_pos, int)):
        try:
            body_seek(body_pos)
        except OSError as e:
            raise UnrewindableBodyError('An error occurred when rewinding request body for redirect/retry.') from e
    elif body_pos is _FAILEDTELL:
        raise UnrewindableBodyError('Unable to record file position for rewinding request body during a redirect/retry.')
    else:
        raise ValueError(f'body_pos must be of type integer, instead it was {type(body_pos)}.')
